 const actions=['menu' ,'meta-custom','meta-milestones','milestone-info','unlock-history','shop-tab','custom-edit','custom-plus','custom-minus','custom-save','custom-cancel','custom-delete','custom-delete-confirm','custom-relic','custom-pick-relic','custom-play','custom-start-confirm','recruit-info','detail-back','discoveries'];if(!actions.includes(d.act))return;e.stopImmediatePropagation();AudioSystem.unlock();AudioSystem.play('click',.25);
