// The engine and abandon() call the internal function; the progression callback covers both.
Progress.onRunEnd=()=>queueMicrotask(()=>{save();exportSave(true);});
let bagDraft=null,bagSelected=null,ownershipFilter='all';
function shapeStamp(id,rotation=0){const cells=G.relicShape(id,rotation),w=Math.max(...cells.map(p=>p[0]))+1,h=Math.max(...cells.map(p=>p[1]))+1;return '<svg class="shape-stamp" viewBox="0 0 '+w*10+' '+h*10+'" aria-hidden="true">'+cells.map(([x,y])=>'<rect x="'+(x*10+1)+'" y="'+(y*10+1)+'" width="8" height="8" rx="1" fill="currentColor"/>').join('')+'</svg>';}
function relicStamp(id,owner){const a=G.ARTIFACTS.find(a=>a.id===id);return '<span class="relic-stamp" style="color:'+Progress.RARITIES[a.rarity].color+'">'+rarityCode(a.rarity)+' · '+shapeStamp(id)+' '+G.relicShape(id).length+'/'+G.bagCapacity(owner)+'</span>';}
function relicDescription(a){return I18n.lang==='pt-BR'?(a.descPT||I18n.t(a.desc)):I18n.t(a.desc);}
function relicTitle(a){return I18n.lang==='pt-BR'?(a.namePT||I18n.t(a.name)):I18n.t(a.name);}
function bagRequired(){return !!(S&&!S.meta?.ended&&(S.pendingRelic||!G.ensureBag(S)));}
function bagView(reset=true){if(!S)return;if(reset||!bagDraft){G.ensureBag(S);bagDraft=[...S.bag.items.map(it=>({...it})),...(S.reserve||[]).map((id,i)=>({id,key:'stock'+i,rotation:0,x:null,y:null}))];if(S.pendingRelic)bagDraft.push({id:S.pendingRelic.id,key:'incoming',rotation:0,x:null,y:null});bagSelected=bagDraft.at(-1)?.key;}
 const readOnly=S.phase==='battle'||!!battle&&!battle.result,selectedItem=bagDraft.find(it=>it.key===bagSelected),a=selectedItem&&G.ARTIFACTS.find(a=>a.id===selectedItem.id),occupied=bagDraft.filter(it=>it.x!==null).reduce((n,it)=>n+G.relicShape(it.id).length,0),valid=G.bagValid(bagDraft.filter(it=>it.x!==null),S);
 const grid=Array.from({length:G.bagCapacity(S)},(_,i)=>{const owner=bagDraft.find(it=>G.bagMask(it,S)!==null&&(G.bagMask(it,S)&(1<<i)));return '<button class="bag-cell '+(owner?'filled':'')+' '+(owner?.key===bagSelected?'selected':'')+'" data-act="bag-cell" data-owner="'+(owner?.key||'')+'" data-pos="'+i+'" style="--piece:'+(owner?Progress.RARITIES[G.ARTIFACTS.find(a=>a.id===owner.id).rarity].color:'#829aa4')+'" aria-label="'+(owner?esc(relicName(owner.id)):L('Empty cell','Célula vazia'))+'">'+(owner?relicIcon(owner.id):'<span>+</span>')+'</button>';}).join('');
 openModal('<h2>'+L('Relic Bag','Bolsa de relíquias')+'</h2><div class="bag-heading"><b>'+occupied+'/'+G.bagCapacity(S)+'</b><span>'+(G.bagCapacity(S)===18?L('4 × 4 + 2 cells','4 × 4 + 2 células'):'4 × 4')+'</span></div>'+(S.pendingRelic?'<div class="bag-incoming">'+L('New relic: ','Nova relíquia: ')+esc(relicName(S.pendingRelic.id))+'</div>':'')+'<div class="bag-grid">'+grid+'</div><div class="bag-inventory">'+bagDraft.map(it=>'<button class="bag-item '+(it.key===bagSelected?'chosen':'')+' '+(it.x===null?'unplaced':'')+'" data-act="bag-select" data-key="'+it.key+'">'+shapeStamp(it.id,it.rotation)+'<span>'+esc(relicName(it.id))+(it.x===null?' · '+L('Stored · inactive','Guardada · inativa'):' · '+L('Active','Ativa'))+'</span></button>').join('')+'</div><div class="bag-detail">'+(a?'<b>'+esc(relicTitle(a))+'</b>'+relicStamp(a.id,S)+'<p>'+esc(relicDescription(a))+'</p>':'')+'</div>'+(readOnly?'<p class="hint">'+L('View only during battle.','Somente consulta durante o combate.')+'</p>'+metaButton('bag-cancel',L('Back','Voltar')):'<p class="hint">'+L('Drag relics to organize the bag. Use Rotate to change their orientation. Stored relics are inactive.','Arraste as relíquias para organizar a bolsa. Use Girar para mudar a orientação. Relíquias guardadas ficam inativas.')+'</p><div class="bag-tools">'+metaButton('bag-rotate',L('Rotate ↻','Girar ↻'))+metaButton('bag-lift',L('Store / move','Guardar / mover'))+metaButton('bag-discard',L('Discard','Descartar'))+'</div><div class="bag-footer">'+metaButton('bag-apply',L('Confirm bag','Confirmar bolsa'),guardAttrs(valid?'':L('Place or discard every unplaced relic.','Encaixe ou descarte as relíquias sem posição.')),'primary')+(S.pendingRelic?metaButton('bag-skip',L('Decline new relic','Recusar nova relíquia')):'')+(!bagRequired()?metaButton('bag-cancel',L('Cancel','Cancelar')):'' )+'</div>'));
 const bagModal=$('overlay').querySelector('.modal');bagModal.classList.add('bag-modal');const bagContent=document.createElement('div');bagContent.className='bag-content';for(const child of [...bagModal.children])if(!child.matches('.close,h2,.bag-tools,.bag-footer,[data-act=bag-cancel]'))bagContent.appendChild(child);bagModal.insertBefore(bagContent,bagModal.querySelector('.bag-tools,.bag-footer,[data-act=bag-cancel]'));if(bagRequired())$('overlay').querySelector('.close').hidden=true;
}
function finishBag(){if(!G.commitBag(S,bagDraft)){toast(L('Unable to confirm. Check space and gold.','Não foi possível confirmar. Confira espaço e ouro.'));return;}bagDraft=null;closeModal();save();render();}
